(async () => {
'use strict';
try {
 await import('./location.js');
 await import('./intake.js');
 await import('./intake-map.js');
 await import('./intake-ui.js');
} catch {
 document.querySelector('#main').textContent = 'Field intake could not load. Please reload. / জমির তথ্যের ফর্ম লোড হয়নি। আবার লোড করুন।';
 return;
}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const criteria=['Water conservation','Soil health','Climate resilience','Cost efficiency','Crop diversity','Stability'];
const crop={Rice:{icon:'🌾',family:'grass',water:90,soil:40,climate:50,cost:40,diversity:50,stability:85,seasons:[0,2]},Maize:{icon:'🌽',family:'grass',water:60,soil:45,climate:65,cost:65,diversity:60,stability:75,seasons:[0,1]},Lentil:{icon:'🫘',family:'legume',water:20,soil:95,climate:80,cost:85,diversity:85,stability:55,seasons:[1]},Mustard:{icon:'🌼',family:'brassica',water:30,soil:65,climate:70,cost:80,diversity:80,stability:65,seasons:[1]},Mungbean:{icon:'🌱',family:'legume',water:25,soil:90,climate:85,cost:80,diversity:90,stability:60,seasons:[0,2]},Vegetables:{icon:'🥬',family:'mixed',water:55,soil:55,climate:55,cost:45,diversity:95,stability:50,seasons:[0,1,2]},Sesame:{icon:'🌿',family:'oilseed',water:15,soil:25,climate:90,cost:85,diversity:80,stability:50,seasons:[0,2]},Jute:{icon:'🍃',family:'fiber',water:70,soil:60,climate:65,cost:55,diversity:80,stability:65,seasons:[0,2]}};
const seasons=['Kharif I · Mar–Jun','Rabi · Nov–Feb','Kharif II · Jul–Oct'];
// Display chronology starts with Kharif I, followed by Kharif II then Rabi.
const seasonOrder=[0,2,1], seasonNames=seasonOrder.map(i=>seasons[i]);
const presets={Balanced:[20,20,20,15,10,15],Water:[45,15,15,10,5,10],Soil:[10,45,15,10,10,10],Resilience:[15,15,45,10,5,10]};
const demoFields=[{id:'rajshahi',name:'Rahim’s North Field',region:'Rajshahi',lat:24.3745,lon:88.6042,size:1.5,soil:'Loam',ph:6.5,organic:1.8,drainage:'Moderate',water:'Limited',history:['Rice','Rice','Mustard'],weights:presets.Water,confidence:'Farmer supplied'},{id:'sylhet',name:'Sylhet Riverside',region:'Sylhet',lat:24.8949,lon:91.8687,size:2.1,soil:'Clay',ph:6.2,organic:2.4,drainage:'Poor',water:'Reliable',history:['Jute','Rice','Lentil'],weights:presets.Balanced,confidence:'Farmer supplied'},{id:'khulna',name:'Khulna Demo Plot',region:'Khulna',lat:22.8456,lon:89.5403,size:1.2,soil:'Sandy loam',ph:6.8,organic:1.2,drainage:'Good',water:'Rain-fed',history:['Sesame','Mungbean','Lentil'],weights:presets.Resilience,confidence:'Illustrative estimate'}];
let stored;try{stored=JSON.parse(localStorage.getItem('sts-studio-v1'));}catch{}
let fields=Array.isArray(stored?.fields)&&stored.fields.length?stored.fields:structuredClone(demoFields),current=fields.some(f=>f.id===stored?.current)?stored.current:fields[0].id;
let route='profile',demoMode=false,metric='rain',chartYear='monthly',sim=null,selected=[],toastTimer;
const intake=window.STS_INTAKE_UI({render,onSubmit:submitted=>{demoMode=false;navigate(submitted?'overview':'profile');},onDemo:()=>{demoMode=true;navigate('overview');},toast});
function field(){return fields.find(f=>f.id===current)||fields[0];}
function persist(){try{localStorage.setItem('sts-studio-v1',JSON.stringify({fields,current}));return true;}catch{toast('Storage unavailable. Changes remain in this session.');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function normalized(w){const total=w.reduce((a,b)=>a+Number(b),0)||1;return w.map(n=>100*n/total);}
function evaluate(sequence,f,scenario='Typical',weights=f.weights){
 const traits=sequence.map(c=>crop[c]),values=['water','soil','climate','cost','diversity','stability'].map(k=>traits.reduce((s,c)=>s+(k==='water'?100-c[k]:c[k]),0)/3);
 const hasLegume=traits.some(c=>c.family==='legume'),familyDiversity=new Set(traits.map(c=>c.family)).size;
 values[1]=Math.min(100,values[1]+(hasLegume?6:0));values[4]=Math.min(100,values[4]+familyDiversity*4);
 if(f.water==='Reliable')values[0]=Math.min(100,values[0]+15);
 if(f.soil==='Sandy loam')values[0]=Math.max(0,values[0]-10);
 if(f.drainage==='Poor')values[2]-=traits.filter(c=>c.family==='legume').length*8;
 if(scenario==='Dry'){values[0]-=traits.reduce((a,c)=>a+c.water,0)/15;values[2]-=sequence.includes('Rice')?15:5;}
 if(scenario==='Hot')values[2]-=sequence.includes('Lentil')?17:7;
 values.forEach((v,i)=>values[i]=Math.max(0,Math.min(100,v)));
 const reasons=[];sequence.forEach((c,i)=>{if(!crop[c].seasons.includes(seasonOrder[i]))reasons.push(`${c} is outside the demo planting window for ${seasonNames[i].split(' ·')[0]}.`);});
 if(f.water==='Rain-fed'&&sequence.includes('Rice'))reasons.push('Rice requires irrigation in this simplified demo rule set.');
 if(Number(f.ph)<5.5&&hasLegume)reasons.push('Legume options are excluded below demo pH threshold 5.5.');
 if(traits[0].family===crop[f.history?.[2]]?.family)values[1]=Math.max(0,values[1]-8);
 const w=normalized(weights),contributions=values.map((v,i)=>v*w[i]/100),score=contributions.reduce((a,b)=>a+b,0);
 return {id:sequence.join('|'),sequence,values,contributions,score,water:Math.round(traits.reduce((s,c)=>s+c.water*5,0)),reasons,feasible:!reasons.length};
}
function rank(f=field(),scenario='Typical',weights=f.weights){const candidates=[];const keys=Object.keys(crop);for(const a of keys)for(const b of keys)for(const c of keys){if(a===b||b===c)continue;candidates.push(evaluate([a,b,c],f,scenario,weights));}return candidates.sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id));}
function valid(f=field(),scenario='Typical',weights=f.weights){return rank(f,scenario,weights).filter(s=>s.feasible);}
const navItems=[['overview','◫','Your results'],['profile','⌖','Set up your field'],['rotations','⇄','Rotation plans'],['compare','⊞','Compare plans'],['simulator','⌁','What-if studio'],['climate','◷','Climate insights'],['saved','♡','Saved plan'],['methodology','◎','Data & methodology']];
function guidance(){
 const data={overview:['Your planning path','Start with field setup, explore the rotation options, then test a scenario before saving a plan.','profile','Review field'],profile:['Your field inputs','Answer all six questions. Scientific planning is not connected yet.','methodology','About the inputs'],rotations:['A score helps you compare','Open a plan to see its weak points as well as its strengths. Add up to three plans for a closer comparison.','compare','Compare plans'],compare:['Read the trade-offs','A high overall score can hide a weak criterion. Compare water demand alongside soil health and resilience.','simulator','Test priorities'],simulator:['Explore safely','Changes here stay in the simulation until you apply priorities and water to your field. Crop swaps are checked immediately. Save a custom plan to keep its scenario assumptions.','rotations','Saved-field plans'],climate:['Evidence has boundaries','These charts show illustrative patterns. Seasonal timing matters, and a regional grid is not a measurement of your field.','methodology','Data context'],methodology:['Know what is real','Your field inputs are saved locally. Environmental values, crop traits, and stress tests are demonstration data.','profile','Your field inputs']}[route];
 return data?`<div class="studio-guide"><span class="studio-guide-mark">◎</span><div><b>${data[0]}</b><p>${data[1]}</p></div><a href="#${data[2]}">${data[3]} ↗</a></div>`:'';
}
function title(kicker,h,p,action=''){return `<div class="page-heading"><div><div class="kicker">${kicker}</div><h1>${h}</h1><p>${p}</p></div>${action}</div>${guidance()}`;}
function scoreBars(s){return `<div class="bars">${s.values.map((v,i)=>`<div class="bar-row"><span>${criteria[i]}</span><div class="track"><div class="fill" style="width:${v}%"></div></div><b>${Math.round(v)}</b></div>`).join('')}</div>`;}
function timeline(s,editable=false){return `<div class="timeline">${s.sequence.map((c,i)=>`<div class="season"><small>${seasonNames[i]}</small><span class="crop-icon">${crop[c].icon}</span>${editable?`<select data-slot="${i}" aria-label="Crop for ${seasonNames[i]}">${Object.keys(crop).map(k=>`<option value="${esc(k)}" ${k===c?'selected':''}>${k}</option>`).join('')}</select>`:`<b>${c}</b>`}<p>${crop[c].family==='legume'?'Legume stage':crop[c].water>65?'Higher water demand':'Moderate to low water demand'}</p></div>`).join('')}</div>`;}
function why(s,f=field()){const w=normalized(f.weights),i=w.indexOf(Math.max(...w));return `<ul class="reasons"><li>${criteria[i]} carries ${Math.round(w[i])}% of your priorities.</li><li>${s.sequence.some(c=>crop[c].family==='legume')?'A legume stage increases the illustrative soil-health score.':'This plan prioritizes other benefits over a legume stage.'}</li><li>Water demand index: ${s.water} demo units across three seasons.</li><li>Trade-off: ${criteria[s.values.indexOf(Math.min(...s.values))].toLowerCase()} is this plan’s weakest criterion.</li></ul>`;}
function chart(kind=metric,year=chartYear){const data={rain:[12,21,37,75,146,241,301,274,212,126,37,15],temp:[19,22,27,30,31,30,29,29,29,27,23,20],moisture:[23,21,20,22,26,34,39,38,36,31,27,24],ndvi:[.52,.55,.59,.64,.61,.65,.71,.73,.69,.64,.58,.53]};let arr=data[kind].slice();const f=field();if(f.region==='Sylhet')arr=arr.map(v=>v*(kind==='rain'?1.35:kind==='moisture'?1.1:1));if(year==='historical')arr=Array.from({length:12},(_,i)=>kind==='rain'?1320+((i*137)%490):kind==='temp'?25.1+i*.09+Math.sin(i)*.35:kind==='moisture'?32-i*.2+Math.sin(i)*2:.6+Math.sin(i)*.06);const min=kind==='temp'?15:kind==='ndvi'?.35:0,max=Math.max(...arr)*1.15;const points=arr.map((v,i)=>[40+i*43,(160-(v-min)/(max-min)*125)]);const path=points.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');const unit={rain:'mm',temp:'°C',moisture:'% volumetric',ndvi:'index'}[kind];return `<svg class="chart" viewBox="0 0 550 205" role="img" aria-label="Illustrative ${kind} ${year} chart"><title>Illustrative ${kind} values, ${unit}; not NASA observations</title>${[0,1,2,3].map(i=>`<line x1="40" x2="518" y1="${35+i*42}" y2="${35+i*42}"/><text x="0" y="${38+i*42}">${(max-(max-min)*i/3).toFixed(kind==='ndvi'?2:0)}</text>`).join('')}<path class="area" d="${path} L513,168 L40,168 Z"/><line class="baseline" x1="40" x2="513" y1="100" y2="100"/><path class="plot" d="${path}"/>${points.map(([x,y],i)=>`<circle tabindex="0" aria-label="${arr[i].toFixed(2)} ${unit}, demo value" cx="${x}" cy="${y}" r="4" fill="var(--surface)" stroke="var(--green)"><title>${year==='monthly'?['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][i]:2014+i}: ${arr[i].toFixed(kind==='ndvi'?2:1)} ${unit} — demo</title></circle>${i%2===0?`<text x="${x}" y="191" text-anchor="middle">${year==='monthly'?['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][i]:2014+i}</text>`:''}`).join('')}</svg><div class="legend">${unit} · Solid: illustrative series · Dashed: illustrative reference level</div>`;}
function metricButtons(){return `<div class="chart-controls">${[['rain','Rainfall'],['temp','Temperature'],['moisture','Soil moisture'],['ndvi','Vegetation']].map(([id,label])=>`<button data-metric="${id}" class="${metric===id?'active':''}" aria-pressed="${metric===id}">${label}</button>`).join('')}</div>`;}
function planningPath(){const f=field();const steps=[['profile','1','Describe your field',f.confirmed?'Field reviewed':'Start here'],['overview','2','Get rotation options','See a three-season plan'],['compare','3','Compare trade-offs','Choose what suits you'],['saved','4','Save your plan',f.saved?'Plan saved':'Keep your shortlist']];return `<div class="planning-path">${steps.map(([r,n,label,sub])=>`<a href="#${r}" class="${route===r?'current':''}"><span>${n}</span><div><b>${label}</b><small>${sub}</small></div></a>`).join('')}</div>`;}
function selectedContext(f=field()){return f.savedContext?{...f,water:f.savedContext.water,weights:f.savedContext.weights}:f;}
function savedResult(f=field()){return f.saved?evaluate(f.saved.split('|'),selectedContext(f),f.savedContext?.scenario||'Typical'):null;}
function overview(){const f=field(),all=valid(),s=all[0];const mainPriority=criteria[normalized(f.weights).indexOf(Math.max(...normalized(f.weights)))];return title('FROM YOUR FIELD TO A PRACTICAL CHOICE',f.confirmed?'Your field. Your next rotation.':'Explore a plan, then make it yours.',f.confirmed?'Your saved inputs shape these demonstration results. Review the benefits, compare alternatives, and keep a plan.':'You are viewing a demo field. Replace these example inputs to explore a plan for your own conditions.',`<button class="primary" data-route="profile">${f.confirmed?'Update field inputs':'Set up my field'} ↗</button>`)+planningPath()+`<div class="input-recap"><div><small>ACTIVE FIELD</small><b>${esc(f.name)}</b></div><div><small>SOIL & WATER</small><b>${esc(f.soil)} · ${esc(f.water)}</b></div><div><small>MAIN PRIORITY</small><b>${mainPriority}</b></div><a href="#profile">Review inputs ↗</a></div><div class="grid main-grid mt"><div class="card decision-card"><div class="row section-head"><div><div class="kicker">${f.confirmed?'YOUR LEADING DEMO OPTION':'EXAMPLE ROTATION'}</div><h3>What could I grow next?</h3></div><span class="tag">THREE-SEASON PLAN</span></div>${s?`<h2 class="plan-name">${s.sequence.join(' → ')}</h2>${timeline(s)}<div class="decision-insights"><div><span>WHY IT FITS YOUR PRIORITIES</span><b>${mainPriority} is your strongest preference.</b><p>This plan scores ${Math.round(s.values[normalized(f.weights).indexOf(Math.max(...normalized(f.weights)))])}/100 for that criterion in the demonstration model.</p></div><div><span>WHAT TO WEIGH CAREFULLY</span><b>${criteria[s.values.indexOf(Math.min(...s.values))]} is its weakest score.</b><p>Use the comparison view to see whether another rotation offers a trade-off you prefer.</p></div></div><div class="actions mt"><button class="primary" data-detail="${esc(s.id)}">Why this plan?</button><button data-route="compare">Compare alternatives</button><button data-save="${esc(s.id)}">${f.saved===s.id?'✓ Saved to your field':'Save this plan'}</button></div><details class="mt"><summary>See the score breakdown · ${s.score.toFixed(1)} / 100</summary><p>Scores express your preferences within a mock model; they do not predict yield.</p>${scoreBars(s)}</details>`:empty()}<div class="notice mt">Prototype result · The inputs are yours, but crop traits and environmental values are illustrative. Review any real planting decision with local agricultural expertise.</div></div><div><div class="card"><div class="row section-head"><h3>Two other possibilities</h3><a href="#rotations">All options ↗</a></div>${all.slice(1,3).map(r=>`<div class="alternative-choice"><h3>${r.sequence.join(' → ')}</h3><p>Strongest criterion: ${criteria[r.values.indexOf(Math.max(...r.values))]}</p><button data-detail="${esc(r.id)}">Review this option ↗</button></div>`).join('')}<a class="full-link" href="#compare">Compare plans side by side ↗</a></div><div class="card mt next-action"><span class="tag">NOT SURE YET?</span><h3 class="mt">Try a change before choosing.</h3><p>What if you had less water, or cared more about soil health?</p><button data-route="simulator">Test a what-if scenario ↗</button></div>${f.saved?`<div class="card mt"><h3>Your saved plan is ready.</h3><p>${f.saved.split('|').join(' → ')}</p><button data-route="saved">Open saved plan ↗</button></div>`:''}</div></div><div class="card mt"><div class="row section-head"><h3>Environmental context, when you need it</h3><a href="#climate">Explore evidence ↗</a></div>${metricButtons()}${chart()}<p class="help">Illustrative regional patterns. Your exact coordinates are saved for future data integration; this prototype does not fetch field-specific NASA observations.</p></div>`;}
function saved(){const f=field(),s=savedResult();return title('YOUR DECISION, KEPT IN ONE PLACE','A plan you can return to.','Review your saved rotation, its assumptions, and the next steps before a real planting decision.')+planningPath()+(s?`<div class="card"><div class="row"><div><div class="kicker">SAVED FOR ${esc(f.name).toUpperCase()}</div><h2>${s.sequence.join(' → ')}</h2></div><span class="tag ${s.feasible?'':'red'}">${s.feasible?'DEMO PLAN':'REVIEW INPUT CHANGES'}</span></div>${timeline(s)}<div class="input-recap"><div><small>WATER ASSUMPTION</small><b>${esc(selectedContext(f).water)}</b></div><div><small>SCENARIO</small><b>${esc(f.savedContext?.scenario||'Typical')}</b></div><div><small>SCORE</small><b>${s.score.toFixed(1)} / 100 · demo</b></div></div>${!s.feasible?`<div class="notice mt">${s.reasons.map(esc).join('<br>')}</div>`:''}<div class="grid g2 mt"><div><h3>Why this plan</h3>${why(s,selectedContext(f))}</div><div><h3>Before you plant</h3><ul class="reasons"><li>Confirm the planting windows and crop varieties with local advice.</li><li>Verify water access and any estimated soil inputs.</li><li>This is a demonstration plan, not a yield or profit forecast.</li></ul></div></div><div class="actions"><button data-action="export" class="primary">Download field & plan</button><button data-action="print">Print / save as PDF ↗</button><button data-detail="${esc(s.id)}">View full explanation</button><button data-action="remove-saved">Remove saved plan</button></div><p class="help mt">Kept in this browser. Saving a new plan replaces this field’s current saved plan.</p></div>`:`<div class="card empty"><span class="saved-empty-symbol">♡</span><h2>You haven’t saved a plan for this field.</h2><p>Start with your results, compare the alternatives, then choose “Save this plan”.</p><button data-route="overview" class="primary">Explore your results ↗</button></div>`);}

function empty(){return `<div class="empty"><h3>No feasible plans for these inputs.</h3><p>Check soil pH and irrigation access, or explore different crops in the simulator.</p><button data-route="profile">Review field profile</button></div>`;}
function options(values,current){return values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function profile(){return intake.form();}
function sliders(weights,target){return `<div class="preset">${Object.keys(presets).map(k=>`<button type="button" data-preset="${k}" data-target="${target}">${k}</button>`).join('')}</div>${weights.map((w,i)=>`<label class="slider-label" for="weight-${i}"><span>${criteria[i]}</span><strong id="weight-label-${i}">${Math.round(normalized(weights)[i])}%</strong></label><input id="weight-${i}" data-weight="${i}" data-target="${target}" type="range" min="0" max="100" value="${w}" aria-label="${criteria[i]} priority">`).join('')}`;}
function rotations(){const f=field(),all=rank(),good=all.filter(s=>s.feasible),bad=all.filter(s=>!s.feasible);return title('ROTATION EXPLORER','A season is part of a bigger story.',`${good.length} feasible sequences from ${all.length} candidates. Compare the top five against your priorities.`,`<button data-route="simulator" class="primary">Open what-if studio ↗</button>`)+`<div class="grid g2">${good.slice(0,5).map((s,i)=>`<div class="card"><div class="row"><span class="tag">${i===0?'TOP MATCH':'OPTION 0'+(i+1)}</span><div class="score">${s.score.toFixed(0)}<small>/100</small></div></div><h2>${s.sequence.join(' → ')}</h2>${timeline(s)}${scoreBars(s)}<div class="actions mt"><button data-detail="${esc(s.id)}" class="primary">View explanation</button><button data-compare="${esc(s.id)}">${selected.includes(s.id)?'✓ Added':'＋ Compare'}</button><button data-save="${esc(s.id)}">${f.saved===s.id?'✓ Saved':'♡ Save'}</button></div></div>`).join('')||empty()}</div><div class="card mt"><details><summary>Why some options were excluded · ${bad.length} sequences</summary><p>Prototype rules check planting windows, irrigation, and a simplified soil pH threshold.</p>${bad.slice(0,8).map(s=>`<div class="alt"><b>${s.sequence.join(' → ')}</b><span class="tag red">${esc(s.reasons[0])}</span></div>`).join('')}</details></div>`;}
function compare(){const all=valid();if(selected.length<2)selected=all.slice(0,3).map(s=>s.id);selected=selected.filter(id=>all.some(s=>s.id===id)).slice(0,3);if(selected.length<2)selected=all.slice(0,3).map(s=>s.id);const chosen=selected.map(id=>all.find(s=>s.id===id));return title('SIDE BY SIDE','Different plans. Clearer trade-offs.','Compare up to three multi-season rotations. Scores use your saved field priorities.')+(chosen.length?`<div class="card table-wrap"><table><thead><tr><th>ROTATION CRITERION</th>${chosen.map((s,i)=>`<th><select data-compare-slot="${i}" aria-label="Comparison plan ${i+1}">${all.map(r=>`<option value="${esc(r.id)}" ${r.id===s.id?'selected':''}>${r.sequence.join(' → ')}</option>`).join('')}</select></th>`).join('')}</tr></thead><tbody><tr><td>Priority-weighted score</td>${chosen.map(s=>`<td><strong>${s.score.toFixed(1)} / 100</strong></td>`).join('')}</tr>${criteria.map((label,i)=>`<tr><td>${label}</td>${chosen.map(s=>`<td>${s.values[i].toFixed(0)}<div class="track mt"><div class="fill" style="width:${s.values[i]}%"></div></div></td>`).join('')}</tr>`).join('')}<tr><td>Water demand index</td>${chosen.map(s=>`<td>${s.water} demo units</td>`).join('')}</tr><tr><td>Plan details</td>${chosen.map(s=>`<td><div class="actions"><button data-detail="${esc(s.id)}">Explore ↗</button><button data-save="${esc(s.id)}">Save this plan</button></div></td>`).join('')}</tr></tbody></table></div><div class="notice mt">Higher criterion scores are preferable; lower water demand is preferable. These comparisons are generated from mock crop traits, not observed yields or validated water requirements.</div>`:empty());}
function simulator(){if(!sim)sim={weights:[...field().weights],water:field().water,scenario:'Typical',sequence:valid()[0]?.sequence.slice()||['Maize','Mungbean','Mustard']};return title('WHAT-IF STUDIO','Small changes. Different possibilities.','Explore how water access, priorities, and crop choices reshape your plan.',`<button data-action="reset-sim">Reset scenario ↺</button>`)+`<div class="grid sim-layout"><div class="card"><div class="kicker">YOUR PLANNING CONTROLS</div><h3>What matters most?</h3>${sliders(sim.weights,'sim')}<label class="slider-label">Water availability</label><select id="sim-water">${options(['Rain-fed','Limited','Reliable'],sim.water)}</select><label class="slider-label">Climate stress test</label><select id="sim-scenario">${options(['Typical','Dry','Hot'],sim.scenario)}</select><p class="help mt">Dry and hot years apply illustrative stress penalties. They are scenarios, not forecasts.</p><button class="primary mt" data-action="apply-sim">Save priorities & water to field</button></div><div><div class="card"><div class="row"><div><div class="kicker">LIVE RANKING</div><h2>See your priorities in action.</h2></div><span class="tag">CLIENT-SIDE DEMO</span></div><div id="sim-results"></div></div><div class="card mt"><div class="row"><h3>Try your own crop sequence</h3><button data-action="swap">Swap first two crops ⇄</button></div>${timeline({sequence:sim.sequence},true)}<div id="custom-result"></div></div></div></div>`;}
function renderSim(){const f={...field(),water:sim.water},base=valid(),all=valid(f,sim.scenario,sim.weights);$('#sim-results').innerHTML=all.slice(0,5).map((s,i)=>{const before=base.find(b=>b.id===s.id),delta=s.score-(before?.score??s.score);return `<div class="rank-item ${i===0?'first':''}"><div class="row"><div><div class="kicker">${String(i+1).padStart(2,'0')} / ${i===0?'LEADING OPTION':'ALTERNATIVE'}</div><h3>${s.sequence.join(' → ')}</h3><span class="delta">${delta>=0?'+':''}${delta.toFixed(1)} points vs saved field</span></div><div class="number">${s.score.toFixed(1)}</div></div><div class="track"><div class="fill" style="width:${s.score}%"></div></div><div class="actions mt"><button data-detail="${esc(s.id)}">Why this option?</button><button data-save="${esc(s.id)}">Save scenario plan</button></div></div>`;}).join('')||empty();const s=evaluate(sim.sequence,f,sim.scenario,sim.weights);$('#custom-result').innerHTML=s.feasible?`<div class="row"><span class="tag">FEASIBLE UNDER DEMO RULES</span><div class="number">${s.score.toFixed(1)} / 100</div></div>${scoreBars(s)}<div class="actions mt"><button data-save="${esc(s.id)}">Save custom plan</button></div>`:`<div class="notice">${s.reasons.map(esc).join('<br>')}</div>`;normalized(sim.weights).forEach((v,i)=>$('#weight-label-'+i).textContent=Math.round(v)+'%');}
function climate(){return title('ENVIRONMENTAL CONTEXT','Read the patterns behind the plan.','Explore illustrative seasonal patterns and historical variability for your active field.')+`<div class="card"><div class="row section-head"><h3>${esc(field().region)} · Environmental evidence preview</h3><span class="tag amber">ILLUSTRATIVE SERIES</span></div><div class="row wrap">${metricButtons()}<div class="chart-controls"><button data-year="monthly" class="${chartYear==='monthly'?'active':''}">Seasonal cycle</button><button data-year="historical" class="${chartYear==='historical'?'active':''}">2014–2025</button></div></div>${chart()}<div class="notice mt">This chart demonstrates the evidence interface using mock values. A future backend will supply quality-controlled NASA observations. Hover or focus on chart points to inspect values.</div></div><div class="grid g3 mt"><div class="card"><span class="tag">RAIN & WATER</span><h3 class="mt">Timing matters as much as totals.</h3><p>Compare rainfall during each crop’s growth window, then assess irrigation access.</p><button data-route="simulator">Explore dry-year scenario ↗</button></div><div class="card"><span class="tag">TEMPERATURE</span><h3 class="mt">Stress-test sensitive seasons.</h3><p>Hot-year scenarios demonstrate how thermal stress can change a plan’s score.</p><button data-route="simulator">Try a hot-year scenario ↗</button></div><div class="card"><span class="tag">SPATIAL LIMITS</span><h3 class="mt">A region is larger than a field.</h3><p>Satellite grids represent an area. Local measurements and your knowledge remain essential.</p><button data-route="methodology">Understand the limitations ↗</button></div></div>`;}
function methodology(){return title('TRANSPARENCY BY DESIGN','Know what’s behind every number.','The prototype shows the workflow. Scientific validation and live data integration remain future work.')+`<div class="card"><div class="kicker">THE DECISION PIPELINE</div><div class="pipeline"><div><small>01 / CONTEXT</small><b>Your field & history</b><p>Location, soil, water, crops</p></div><div><small>02 / FEASIBILITY</small><b>Filter candidate sequences</b><p>Season, water, pH demo rules</p></div><div><small>03 / PRIORITIES</small><b>Weight six criteria</b><p>Normalized preferences</p></div><div><small>04 / EXPLANATION</small><b>Rank & compare plans</b><p>Scores, reasons, trade-offs</p></div></div></div><div class="grid g2 mt"><div class="card"><h2>Planned evidence sources</h2>${[['NASA POWER','Meteorological and solar context','https://power.larc.nasa.gov/'],['GPM IMERG','Rainfall history and variability','https://gpm.nasa.gov/data/imerg'],['SMAP','Regional soil-moisture context','https://smap.jpl.nasa.gov/'],['MODIS / VIIRS','Vegetation greenness evidence','https://www.earthdata.nasa.gov/']].map(([name,desc,url])=>`<div class="data-source"><div><b>${name}</b><p>${desc}</p><span class="tag amber">NOT CONNECTED</span></div><a href="${url}" target="_blank" rel="noopener">Official source ↗</a></div>`).join('')}</div><div class="card"><h2>How to read the results</h2><details open><summary>What does the score mean?</summary><p>Each crop has six illustrative traits. We average traits over the sequence, add simple soil/diversity adjustments, normalize your weights to 100%, and sum weighted contributions. Scores express preferences within this mock model; they do not predict yield or guarantee success.</p></details><details><summary>Which rules exclude plans?</summary><p>Each crop has demo planting windows. Consecutive identical crops are not generated. Rain-fed fields exclude rice in this simplified model; legumes are excluded below pH 5.5. These rules require local agronomic validation.</p></details><details><summary>What about uncertainty?</summary><p>No statistical confidence intervals or rank-stability probabilities are computed in this prototype. Historical replay and Monte Carlo sensitivity are planned backend features. We avoid displaying invented confidence percentages.</p></details><details><summary>Observed, derived, and scenario data</summary><p>Observed: measurements or assimilated observations from connected datasets. Derived: quantities calculated from them. Scenario: assumptions applied for comparison. Currently, all environmental values are illustrative, and dry/hot controls are mock scenarios.</p></details><details><summary>Privacy & saved data</summary><p>Fields and saved plans remain in browser local storage. They do not sync across devices. JSON export includes your field inputs and a demo label. Use the reset button below to restore the example fields.</p><button data-action="reset-data">Restore demo fields</button></details><details><summary>Boundaries of this tool</summary><p>No yield forecasts, irrigation schedules, fertilizer prescriptions, market prices, or pest diagnosis. A prototype recommendation should never replace local agricultural expertise.</p></details></div></div>`;}
function showDetails(id){const sequence=id.split('|');if(sequence.length!==3||sequence.some(c=>!crop[c]))return;const f=field(),context=route==='saved'&&f.saved===id?selectedContext(f):route==='simulator'&&sim?{...f,water:sim.water,weights:sim.weights}:f,s=evaluate(sequence,context,route==='saved'&&f.saved===id?(f.savedContext?.scenario||'Typical'):route==='simulator'&&sim?sim.scenario:'Typical'),demand=sequence.map(c=>crop[c].water*5);$('#detail-content').innerHTML=`<div class="row"><span class="tag">ROTATION DETAIL / DEMO</span><button data-action="close-dialog" aria-label="Close details">✕</button></div><h1 class="mt">${sequence.join(' → ')}</h1><div class="row"><p>Three seasons · ${esc(f.name)}</p><div class="score">${s.score.toFixed(1)}<small>/100</small></div></div>${timeline(s)}${!s.feasible?`<div class="notice">${s.reasons.map(esc).join('<br>')}</div>`:''}<div class="grid g2"><div><h3>Criterion scores</h3>${scoreBars(s)}${why(s,context)}</div><div><h3>Weighted contributions</h3>${s.contributions.map((v,i)=>`<div class="alt"><span>${criteria[i]}</span><b>${v.toFixed(1)} points</b></div>`).join('')}</div></div><div class="grid g2 mt"><div><h3>Water demand by season</h3><div class="water-bars">${demand.map((v,i)=>`<div class="water-group"><div><i style="height:${v/4}px" title="Demand ${v} demo units"></i><i style="height:${Math.min(120,v/(context.water==='Reliable'?4:8))}px" title="Illustrative available water"></i></div>${sequence[i]}</div>`).join('')}</div><div class="legend"><span><b style="background:#658f70"></b>Demand</span><span><b style="background:#c6d5a0"></b>Illustrative available water</span></div></div><div><h3>Illustrative risk indicators</h3><div class="risk-grid"><span>Season</span><span>Drought</span><span>Heat</span><span>Waterlogging</span>${sequence.map(c=>{const r=crop[c];return `<span>${c}</span><span class="${r.water>65?'high':'low'}">${r.water>65?'High':'Low'}</span><span class="${r.climate<60?'medium':'low'}">${r.climate<60?'Medium':'Low'}</span><span class="${r.family==='legume'?'medium':'low'}">${r.family==='legume'?'Medium':'Low'}</span>`;}).join('')}</div><p class="help mt">Risk labels are derived from simplified mock traits, not an environmental risk model.</p></div></div><div class="notice mt">Uncertainty analysis is not calculated in this frontend. No validated recommendation or forecast is implied.</div><div class="actions mt"><button data-save="${esc(s.id)}" class="primary">Save this plan</button><button data-action="print">Print / save as PDF ↗</button></div>`;$('#details').showModal();}
function render(){
 intake.beforeRender();
 route=location.hash.slice(1)||(intake.hasSubmission()?'overview':'profile');
 if(!navItems.some(n=>n[0]===route))route='profile';
 if(route==='profile')demoMode=false;
 $('#nav').innerHTML=navItems.map(([id,icon,label])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span>${icon}</span>${label}</a>`).join('');
 $('#crumb').textContent=navItems.find(n=>n[0]===route)[2];
 $('#field-select').innerHTML=fields.map(f=>`<option value="${esc(f.id)}" ${demoFields.some(d=>d.name===f.name)?'':'data-no-translate'} ${current===f.id?'selected':''}>${esc(f.name)}</option>`).join('');
 $('#field-select').hidden=!demoMode;
 const bn=document.documentElement.lang==='bn';
 $('.field-switch small').textContent=demoMode?(bn?'নমুনা জমি':'DEMO FIELD'):(bn?'আপনার জমির তথ্য':'YOUR FIELD INPUTS');
 $('.demo-dot').textContent=demoMode?(bn?'আলাদা নমুনা ডেমো':'Separate illustrative demo'):(bn?'জমির তথ্য · পরিকল্পনা অনুপলব্ধ':'Field inputs · planning unavailable');
 const exportButton=$('header [data-action="export"]');
 exportButton.textContent=demoMode?(bn?'নমুনা রপ্তানি':'Export demo'):(bn?'তথ্য রপ্তানি':'Export inputs');
 exportButton.disabled=!demoMode&&!intake.hasSubmission();
 if(!demoMode)$('#main').innerHTML=route==='profile'?intake.form():intake.summary();
 else {
  $('#main').innerHTML=`<div class="notice demo-separation" data-no-translate><b>${bn?'আলাদা নমুনা ডেমো · আপনার জমির তথ্য ব্যবহার করা হচ্ছে না।':'Separate illustrative demo · your intake answers are not used here.'}</b><button data-action="return-intake">${bn?'জমির তথ্যে ফিরুন':'Return to field inputs'}</button></div>`+({overview,rotations,compare,simulator,climate,methodology,saved}[route])();
  if(route==='simulator')renderSim();
 }
 intake.afterRender();
 $('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');
}
function navigate(r){if(location.hash==='#'+r)render();else location.hash=r;}
function syncThemeLabel(){const dark=document.body.classList.contains('dark');$('#theme').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');$('#theme').title=dark?'Switch to light mode':'Switch to dark mode';}
$('#theme').addEventListener('click',()=>{document.body.classList.toggle('dark');syncThemeLabel();try{localStorage.setItem('sts-studio-theme',document.body.classList.contains('dark')?'dark':'light');}catch{}});try{document.body.classList.toggle('dark',(localStorage.getItem('sts-studio-theme')||'light')==='dark');}catch{}syncThemeLabel();
$('#menu').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String($('#sidebar').classList.contains('open')));});
$('#field-select').addEventListener('change',e=>{current=e.target.value;sim=null;selected=[];persist();render();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.route){navigate(d.route);return;}if(d.detail){showDetails(d.detail);return;}if(d.metric){metric=d.metric;render();return;}if(d.year){chartYear=d.year;render();return;}if(d.preset&&demoMode&&sim){sim.weights=[...presets[d.preset]];render();return;}if(d.compare){if(selected.includes(d.compare))selected=selected.filter(id=>id!==d.compare);else if(selected.length<3)selected.push(d.compare);else return toast('Compare up to three plans. Remove one first.');toast(`${selected.length} plan${selected.length===1?'':'s'} selected for comparison`);render();return;}if(d.save){const f=field();f.saved=d.save;f.savedContext=route==='saved'&&f.savedContext?f.savedContext:route==='simulator'&&sim?{scenario:sim.scenario,water:sim.water,weights:[...sim.weights]}:{scenario:'Typical',water:f.water,weights:[...f.weights]};persist();toast('Plan saved. Open Saved plan to review or export it.');if(!$('#details').open)render();return;}switch(d.action){case 'new-field':intake.newDraft();demoMode=false;sim=null;selected=[];navigate('profile');break;case 'return-intake':demoMode=false;navigate('profile');break;case 'reset-sim':sim=null;render();break;case 'apply-sim':field().weights=[...sim.weights];field().water=sim.water;persist();toast('Priorities and irrigation saved. Climate scenario remains a simulation.');renderSim();break;case 'swap':[sim.sequence[0],sim.sequence[1]]=[sim.sequence[1],sim.sequence[0]];render();break;case 'close-dialog':$('#details').close();break;case 'print':window.print();break;case 'export':{if(!demoMode){intake.download();break;}const f=field();const best=f.saved?savedResult(f):valid()[0];const blob=new Blob([JSON.stringify({prototype:true,dataClass:'illustrative',field:f,plan:best||null,warning:'Not validated agricultural advice. No NASA data integration.'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='soil-to-stars-field-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo field and plan exported');break;}case 'remove-saved':delete field().saved;delete field().savedContext;persist();render();toast('Saved plan removed from this field');break;case 'reset-data':fields=structuredClone(demoFields);current=fields[0].id;sim=null;selected=[];persist();render();toast('Example fields restored');break;}});
document.addEventListener('input',e=>{const d=e.target.dataset;if(d.weight!==undefined&&demoMode&&sim){const w=sim.weights;w[Number(d.weight)]=Number(e.target.value);if(w.every(n=>n===0)){w[Number(d.weight)]=1;e.target.value=1;}renderSim();}});
document.addEventListener('change',e=>{if(!demoMode)return;if(e.target.id==='sim-water'){sim.water=e.target.value;renderSim();}if(e.target.id==='sim-scenario'){sim.scenario=e.target.value;renderSim();}if(e.target.dataset.slot!==undefined){sim.sequence[Number(e.target.dataset.slot)]=e.target.value;renderSim();}if(e.target.dataset.compareSlot!==undefined){const slot=Number(e.target.dataset.compareSlot),id=e.target.value;if(selected.some((s,i)=>i!==slot&&s===id)){toast('Choose a different plan for each column');render();return;}selected[slot]=id;render();}});
document.addEventListener('sts-language-change',()=>{const focused=document.activeElement?.id;render();if(focused)document.getElementById(focused)?.focus({preventScroll:true});});
window.addEventListener('hashchange',render);$('#details').addEventListener('click',e=>{if(e.target===$('#details'))$('#details').close();});render();
})();
